    ) AS data(code, template_version, name, category, orientation, width, height, config, display_order)
    LOOP
        SELECT count(*) INTO matches FROM page_templates
            WHERE code = seed.code AND template_version = seed.template_version;
        IF matches > 1 THEN
            RAISE EXCEPTION 'Ambiguous existing page template: % / %', seed.code, seed.template_version;
        END IF;
        IF EXISTS (SELECT 1 FROM page_templates WHERE code = seed.code AND template_version = seed.template_version
            AND (canvas_width IS DISTINCT FROM seed.width OR canvas_height IS DISTINCT FROM seed.height
                 OR orientation IS DISTINCT FROM seed.orientation)) THEN
            RAISE EXCEPTION 'Conflicting existing page template geometry: % / %', seed.code, seed.template_version;
        END IF;
        INSERT INTO page_templates(code, template_version, name, category, orientation, canvas_width, canvas_height, default_config, display_order)
            SELECT seed.code, seed.template_version, seed.name, seed.category, seed.orientation, seed.width, seed.height, seed.config, seed.display_order
            WHERE NOT EXISTS (SELECT 1 FROM page_templates WHERE code = seed.code AND template_version = seed.template_version);
    END LOOP;
END
